def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    r,c=next((r,c) for r in range(h) for c in range(w) if grid[r][c]==2)
    tracks={c}
    for wall in range(r+1,h):
        if not any(v==8 for v in grid[wall]):
            for x in tracks: out[wall][x]=2
            continue
        gaps=[x for x,v in enumerate(grid[wall]) if v!=8]
        nxt=set()
        for x in tracks:
            if x in gaps:
                nxt.add(x); continue
            lo=[g for g in gaps if g<x]; hi=[g for g in gaps if g>x]
            if lo and hi:
                a,b=max(lo),min(hi)
                for z in range(a,b+1): out[wall-1][z]=2
                nxt.update((a,b))
            elif lo:
                a=max(lo)
                for z in range(min(a,x),max(a,x)+1): out[wall-1][z]=2
                nxt.add(a)
            elif hi:
                b=min(hi)
                for z in range(min(b,x),max(b,x)+1): out[wall-1][z]=2
                nxt.add(b)
        tracks=nxt
        for x in tracks: out[wall][x]=2
    return out

